  const save = () => create.mutate({ name: form.name, email: form.email, phone: form.phone, password: form.password, ...(form.branchId ? { branchId: Number(form.branchId) } : form.branchName.trim() ? { branchName: form.branchName.trim() } : {}) });
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="branch-user-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">إدارة المستخدمين</p><h2 id="branch-user-title" className="mt-1 text-lg font-extrabold text-[#173f38]">إضافة مستخدم فرع</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose}><X size={19} /></button></div><div className="grid gap-4 p-6 sm:grid-cols-2"><label className="block text-[10px] font-bold text-[#4e6860]">اسم المستخدم<input className="input-control mt-2" value={form.name} onChange={event => update("name", event.target.value)} /></label><label className="block text-[10px] font-bold text-[#4e6860]">البريد الإلكتروني<input className="input-control mt-2" type="email" dir="ltr" value={form.email} onChange={event => update("email", event.target.value)} /></label><label className="block text-[10px] font-bold text-[#4e6860]">رقم تواصل الفرع<input className="input-control mt-2" dir="ltr" value={form.phone} onChange={event => update("phone", event.target.value)} placeholder="05XXXXXXXX" /></label><label className="block text-[10px] font-bold text-[#4e6860]">كلمة المرور<input className="input-control mt-2" type="password" value={form.password} onChange={event => update("password", event.target.value)} /></label><label className="block text-[10px] font-bold text-[#4e6860]">فرع قائم<select className="filter-select mt-2 w-full" value={form.branchId} onChange={event => { update("branchId", event.target.value); if (event.target.value) update("branchName", ""); }}><option value="">إنشاء أو اختيار اسم جديد</option>{branches.data?.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label>{!form.branchId && <label className="block text-[10px] font-bold text-[#4e6860] sm:col-span-2">اسم فرع جديد<input className="input-control mt-2" value={form.branchName} onChange={event => update("branchName", event.target.value)} placeholder="مثال: فرع العزيزية" /></label>}</div><p className="px-6 pb-4 text-[10px] text-[#7b8f87]">رقم التواصل يُطبع تلقائياً في تذاكر حجوزات الفرع الجديدة وتصديرات ركابه.</p><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" disabled={create.isPending || !form.name || !form.email || form.phone.trim().length < 7 || form.password.length < 8 || (!form.branchId && !form.branchName.trim())} onClick={save}><UserPlus size={15} /> حفظ المستخدم</button></div></div></div>;
