function UserFormInput({ label, value, onChange, placeholder, type = "text", direction }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; direction?: "ltr" | "rtl" }) {
  return <label className="block text-[10px] font-bold text-[#4e6860]">{label}<input className="input-control mt-2" value={value} onChange={event => onChange(event.target.value)} placeholder={placeholder} type={type} dir={direction} /></label>;
}

function BranchUserModal({ onClose }: { onClose: () => void }) {
  const utils = trpc.useUtils();
  const FormInput = UserFormInput;
  const branches = trpc.mongoBooking.admin.branches.list.useQuery(undefined, { retry: false, refetchOnWindowFocus: false });
  const [form, setForm] = useState({ name: "", email: "", phone: "", password: "", branchName: "", branchId: "", branchLocationUrl: "" });
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const create = trpc.mongoBooking.admin.users.create.useMutation({
    onSuccess: () => { void utils.mongoBooking.admin.users.list.invalidate(); void utils.mongoBooking.admin.branches.list.invalidate(); toast.success("تم إنشاء مستخدم الفرع وحفظ بيانات التواصل والموقع."); onClose(); },
    onError: error => toast.error(error.message),
  });
  const save = () => {
    const locationUrl = form.branchLocationUrl.trim();
    if (locationUrl) {
      try { new URL(locationUrl); } catch { toast.error("أدخل رابط موقع الفرع بصيغة صحيحة."); return; }
    }
    create.mutate({
      name: form.name,
      email: form.email,
      phone: form.phone,
      password: form.password,
      branchLocationUrl: locationUrl || null,
      ...(form.branchId ? { branchId: Number(form.branchId) } : { branchName: form.branchName.trim() }),
    });
  };
  const canSave = !create.isPending && form.name.trim().length >= 3 && form.email.trim() && form.phone.trim().length >= 7 && form.password.length >= 8 && Boolean(form.branchId || form.branchName.trim());
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="branch-user-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">إدارة المستخدمين</p><h2 id="branch-user-title" className="mt-1 text-lg font-extrabold text-[#173f38]">إضافة مستخدم فرع</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose} aria-label="إغلاق"><X size={19} /></button></div><div className="grid gap-4 p-6 sm:grid-cols-2"><FormInput label="اسم المستخدم" value={form.name} onChange={value => update("name", value)} placeholder="اسم مسؤول الفرع" /><FormInput label="البريد الإلكتروني" value={form.email} onChange={value => update("email", value)} type="email" direction="ltr" placeholder="branch@example.com" /><FormInput label="رقم تواصل الفرع" value={form.phone} onChange={value => update("phone", value)} direction="ltr" placeholder="05XXXXXXXX" /><FormInput label="كلمة المرور" value={form.password} onChange={value => update("password", value)} type="password" placeholder="8 أحرف أو أكثر" /><label className="block text-[10px] font-bold text-[#4e6860]">فرع قائم<select className="filter-select mt-2 w-full" value={form.branchId} onChange={event => { update("branchId", event.target.value); if (event.target.value) update("branchName", ""); }}><option value="">إنشاء فرع جديد أو اختر فرعاً</option>{branches.data?.map(branch => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label>{!form.branchId && <FormInput label="اسم الفرع الجديد" value={form.branchName} onChange={value => update("branchName", value)} placeholder="مثال: فرع العزيزية" />}<div className="sm:col-span-2"><FormInput label="رابط موقع الفرع (Google Maps مثلاً)" value={form.branchLocationUrl} onChange={value => update("branchLocationUrl", value)} direction="ltr" placeholder="https://maps.google.com/..." /><p className="mt-2 text-[10px] text-[#7b8f87]">يظهر اسم الفرع ورقم التواصل والرابط في رسالة واتساب الخاصة بعملاء حجوزات هذا الفرع.</p></div></div><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" disabled={!canSave} onClick={save}><UserPlus size={15} /> حفظ المستخدم</button></div></div></div>;
}

function LegacyTripsPage({ onNewTrip, trips, canManageTrips }: { onNewTrip: () => void; trips: TripItem[]; canManageTrips: boolean }) {
  const navigate = useNavigate();
  return <><PageHeader kicker="إدارة التشغيل" title="الرحلات" description={canManageTrips ? "أضف بيانات الرحلة والسائقين والسعة، ثم تابع المقاعد والحالة التشغيلية." : "اختر رحلة لعرض المقاعد المتاحة وتسجيل حجوزات فرعك."} action={canManageTrips ? <button className="action-primary" onClick={onNewTrip}><Plus size={16} /> إضافة رحلة</button> : undefined} /><div className="soft-card overflow-hidden"><div className="flex flex-wrap items-center gap-3 border-b border-[#edf0ed] p-5"><div className="relative min-w-[220px] flex-1"><Search size={15} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[#8da09b]" /><input className="input-control pr-9" placeholder="ابحث بالمسار أو رقم الحافلة" /></div><select className="filter-select"><option>جميع الحالات</option><option>متاح</option><option>مكتمل</option></select><button className="action-secondary"><Filter size={14} /> تصفية</button></div>{trips.length === 0 ? <div className="p-12 text-center"><BusFront className="mx-auto text-[#80a095]" size={32} /><h2 className="mt-4 text-sm font-extrabold text-[#284f45]">لا توجد رحلات مسجلة بعد</h2><p className="mt-2 text-[11px] text-[#7e908a]">{canManageTrips ? "أضف أول رحلة لتبدأ الحجز والمتابعة." : "لا توجد رحلة متاحة للحجز حالياً."}</p>{canManageTrips && <button className="action-primary mt-5" onClick={onNewTrip}><Plus size={15} /> إضافة أول رحلة</button>}</div> : <div className="table-wrap"><table className="data-table"><thead><tr><th>رقم الرحلة</th><th>المسار</th><th>المغادرة</th><th>الحافلة / السائقان</th><th>المقاعد</th><th>الإشغال</th><th>الحالة</th><th /></tr></thead><tbody>{trips.map(item => { const occupied = item.bookedSeats.length; const occupancy = Math.round((occupied / item.capacity) * 100); const tone = item.status === "closed" ? "red" : item.status === "boarding" ? "amber" : "green"; const label = item.status === "closed" ? "مكتمل" : item.status === "boarding" ? "تجهيز" : "متاح"; return <tr key={item.code}><td className="font-bold text-[#1d5b4d]">{item.code}</td><td><p className="font-semibold">{item.route}</p></td><td><div className="flex items-center gap-1.5"><Clock3 size={13} className="text-[#7a948b]" />{item.time}</div></td><td><p className="font-semibold">{item.bus}</p><p className="mt-1 text-[9px] text-[#607871]">الأول: {item.driver}</p><p className="mt-1 text-[9px] text-[#8b9c97]">الثاني: {item.secondDriver || "غير محدد"}</p></td><td className="font-semibold">{occupied} / {item.capacity}</td><td><div className="flex items-center gap-2"><div className="h-1.5 w-14 overflow-hidden rounded-full bg-[#edf2ed]"><div className="h-full rounded-full bg-[#4b927d]" style={{ width: `${occupancy}%` }} /></div><span className="text-[9px] text-[#6d817a]">{occupancy}%</span></div></td><td><Badge tone={tone}>{label}</Badge></td><td><button className="inline-flex items-center gap-1 text-[10px] font-bold text-[#2c7c66]" onClick={() => navigate(`/trips/${item.code}`)}><Eye size={14} /> تفاصيل الرحلة</button></td></tr>; })}</tbody></table></div>}</div></>;
}

function ReservationsPage({ onNewReservation }: { onNewReservation: () => void }) {
  return <><PageHeader kicker="مركز الحجوزات" title="الحجوزات" description="سجل جديد موحد للراكب والسعر والمقعد وحالة التحصيل والفرع." action={<button className="action-primary" onClick={onNewReservation}><Plus size={16} /> حجز جديد</button>} /><div className="soft-card overflow-hidden"><div className="grid gap-3 border-b border-[#edf0ed] p-5 md:grid-cols-[1fr_auto_auto]"><div className="relative"><Search size={15} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[#8da09b]" /><input className="input-control pr-9" placeholder="البحث باسم الراكب أو رقم الحجز" /></div><select className="filter-select"><option>كل الفروع</option><option>العزيزية</option><option>الشمال</option></select><select className="filter-select"><option>كل حالات الدفع</option><option>مدفوع</option><option>جزئي</option><option>غير مدفوع</option></select></div><div className="table-wrap"><table className="data-table"><thead><tr><th>رقم الحجز</th><th>بيانات الراكب</th><th>الرحلة</th><th>المقعد</th><th>الفرع</th><th>السعر</th><th>حالة الدفع</th><th /></tr></thead><tbody>{reservations.map(item => <tr key={item.id}><td className="font-bold text-[#1e5b4d]">{item.id}</td><td><p className="font-semibold">{item.passenger}</p><p className="mt-1 text-[9px] text-[#92a09c]" dir="ltr">{item.phone}</p></td><td>{item.trip}</td><td><span className="rounded-lg bg-[#eef6f1] px-2 py-1 font-bold text-[#397663]">{item.seat}</span></td><td>{item.branch}</td><td className="font-semibold">{item.amount}</td><td><Badge tone={item.tone}>{item.payment}</Badge></td><td><button className="text-[10px] font-bold text-[#2d7a60]" onClick={() => toast.info(`تم فتح تفاصيل الحجز ${item.id}.`)}>تفاصيل</button></td></tr>)}</tbody></table></div></div></>;
}

function CustomersPage() { return <><PageHeader kicker="سجل المسافرين" title="العملاء" description="اعرض بيانات المسافرين وسجل حجوزاتهم لإتمام الخدمة بصورة أسرع." action={<button className="action-secondary" onClick={() => toast.info("يتم إنشاء العميل تلقائياً عند حفظ الحجز.")}><Plus size={15} /> عميل جديد</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{reservations.concat([{ id: "#SH-2407", passenger: "هند الرشيد", phone: "050 229 5521", trip: "الرياض ← المدينة", seat: "D10", branch: "الشمال", amount: "175 ر.س", payment: "مدفوع", tone: "green" }]).map((item, index) => <div className="soft-card p-5" key={item.id}><div className="flex items-start justify-between"><span className="avatar-dot h-11 w-11 rounded-xl text-sm">{item.passenger.charAt(0)}</span><Badge tone={index % 3 === 0 ? "blue" : "green"}>{index + 1} حجوزات</Badge></div><h2 className="mt-4 text-sm font-extrabold text-[#274d44]">{item.passenger}</h2><p className="mt-2 text-[10px] text-[#7f928d]" dir="ltr">{item.phone}</p><div className="mt-5 flex items-center justify-between border-t border-[#eef1ee] pt-4 text-[10px]"><span className="text-[#84948f]">آخر رحلة</span><span className="font-semibold text-[#49635c]">{item.trip}</span></div></div>)}</div></> }

function CashboxPage({ userMode }: { userMode: UserMode }) { return <><PageHeader kicker="مالية التشغيل" title="الخزنة" description={userMode === "admin" ? "نظرة موحدة على رصيد الفروع والتحصيلات والحركات المالية." : "تابع الرصيد والتحصيلات الخاصة بفرع العزيزية."} action={<div className="flex gap-2"><button className="action-secondary" onClick={() => toast.success("تم فتح نموذج سند الصرف.")}><ArrowDownLeft size={15} /> سند صرف</button><button className="action-primary" onClick={() => toast.success("تم فتح نموذج سند القبض.")}><ArrowUpLeft size={15} /> سند قبض</button></div>} /><div className="grid gap-4 md:grid-cols-3"><BalanceCard title="الرصيد النقدي" amount={userMode === "admin" ? "13,980" : "4,850"} icon={Banknote} color="#2e7b62" tint="#e7f2ec" /><BalanceCard title="رصيد البنك" amount={userMode === "admin" ? "26,440" : "8,300"} icon={WalletCards} color="#3678a3" tint="#e8f1f8" /><BalanceCard title="تحصيلات اليوم" amount={userMode === "admin" ? "8,460" : "2,975"} icon={TrendingUp} color="#977131" tint="#fff3de" /></div><section className="soft-card mt-5 overflow-hidden"><div className="flex items-center justify-between border-b border-[#edf0ed] p-5"><div><h2 className="section-title">آخر الحركات</h2><p className="mt-1 section-meta">حركات القبض والصرف المسجلة اليوم</p></div><span className="section-meta">بيانات العرض</span></div><div className="table-wrap"><table className="data-table"><thead><tr><th>الحركة</th><th>الفرع</th><th>البيان</th><th>الوقت</th><th>المبلغ</th><th>الحالة</th></tr></thead><tbody>{[{ type: "قبض", branch: "العزيزية", detail: "حجز #SH-2418", time: "10:42 ص", amount: "+175 ر.س", tone: "green" }, { type: "صرف", branch: "الشمال", detail: "وقود الرحلة SH-204", time: "09:10 ص", amount: "-480 ر.س", tone: "red" }, { type: "قبض", branch: "النسيم", detail: "حجز #SH-2415", time: "08:26 ص", amount: "+120 ر.س", tone: "green" }].map(item => <tr key={item.detail}><td><Badge tone={item.tone}>{item.type}</Badge></td><td>{item.branch}</td><td>{item.detail}</td><td>{item.time}</td><td className={item.tone === "green" ? "font-bold text-[#2f835c]" : "font-bold text-[#c75c49]"}>{item.amount}</td><td><CheckCircle2 size={16} className="text-[#55a576]" /></td></tr>)}</tbody></table></div></section></> }

function BalanceCard({ title, amount, icon: Icon, color, tint }: { title: string; amount: string; icon: typeof Banknote; color: string; tint: string }) { return <div className="soft-card p-5"><div className="flex items-center justify-between"><div className="grid h-10 w-10 place-items-center rounded-xl" style={{ color, background: tint }}><Icon size={19} /></div><span className="text-[10px] text-[#7f928c]">هذا الشهر</span></div><p className="mt-6 text-2xl font-extrabold tracking-[-.06em] text-[#173f38]">{amount} <span className="text-xs tracking-normal">ر.س</span></p><p className="mt-2 text-[11px] text-[#71847e]">{title}</p></div> }

